Text:
```python
values = {
    "Person 1": {"A": 5, "B": 47, "C": 45, "D": 3},
    "Person 2": {"A": 45, "B": 5, "C": 48, "D": 2},
    "Person 3": {"A": 23, "B": 25, "C": 32, "D": 20}
}

allocation = {}
for good in ["A", "B", "C", "D"]:
    max_value = -1
    assigned_person = None
    for person in ["Person 1", "Person 2", "Person 3"]:
        if values[person][good] > max_value:
            max_value = values[person][good]
            assigned_person = person
    allocation[good] = assigned_person

print(allocation)
```
```
{'A': 'Person 2', 'B': 'Person 1', 'C': 'Person 2', 'D': 'Person 3'}
```

