```python
values = {
    'Person 1': {'A': 5, 'B': 47, 'C': 45, 'D': 3},
    'Person 2': {'A': 45, 'B': 5, 'C': 48, 'D': 2},
    'Person 3': {'A': 23, 'B': 25, 'C': 32, 'D': 20}
}

allocation = {}
for good in ['A', 'B', 'C', 'D']:
    max_value = max([values[person][good] for person in values])
