```python
values = {
    'Person 1': {'A': 5, 'B': 47, 'C': 45, 'D': 3},
    'Person 2': {'A': 45, 'B': 5, 'C': 48, 'D': 2},
    'Person 3': {'A': 23, 'B': 25, 'C': 32, 'D': 20}
}

assignment = {}
unassigned = ['A', 'B', 'C', 'D']

while unassigned:
  best_good = None
  best_person = None
  max_value = float('-inf')

  for good in unassigned:
    for person in values:
      if values[person][good] > max_value:
        max_value = values[person][good]
        best_person = person
        best_good = good

  if best_good is not None:
    assignment[best_good] = best_person
    unassigned.remove(best_good)

print(assignment)
```

