```python
values = {
    "Person 1": {"A": 5, "B": 47, "C": 45, "D": 3},
    "Person 2": {"A": 45, "B": 5, "C": 48, "D": 2},
    "Person 3": {"A": 23, "B": 25, "C": 32, "D": 20}
}

allocation = {
    "Person 1": [],
    "Person 2": [],
    "Person 3": []
}

while len(values) > 0:
    highest_value = -1
    highest_value_person = None
    highest_value_good = None

    for person in values:
        for good in values[person]:
            if values[person][good] > highest_value:
                highest_value = values[person][good]
                highest_value_person = person
                highest_value_good = good

    allocation[highest_value_person].append(highest_value_good)
    for person in values:
        if highest_value_good in values[person]:
            del values[person][highest_value_good]

    if len(values[highest_value_person]) == 0:
        del values[highest_value_person]

print(allocation)
```

