```python
values = {
    'Person 1': {'A': 5, 'B': 47, 'C': 45, 'D': 3},
    'Person 2': {'A': 45, 'B': 5, 'C': 48, 'D': 2},
    'Person 3': {'A': 23, 'B': 25, 'C': 32, 'D': 20}
}

assignment = {}
unassigned = list(values['Person 1'].keys())

while unassigned:
    best_item = None
    best_person = None
    max_value = float('-inf')

    for person in values:
        for item in unassigned:
            if values[person][item] > max_value:
                max_value = values[person][item]
                best_person = person
                best_item = item

    assignment[best_item] = best_person
    unassigned.remove(best_item)

print(assignment) 
```

Output: 
```
{'B': 'Person 1', 'C': 'Person 2', 'A': 'Person 2', 'D': 'Person 3'}
```

