values = {
    'Person 1': {'A': 5, 'B': 47, 'C': 45, 'D': 3},
    'Person 2': {'A': 45, 'B': 5, 'C': 48, 'D': 2},
    'Person 3': {'A': 23, 'B': 25, 'C': 32, 'D': 20}
}

assignment = {}
unassigned = ['A', 'B', 'C', 'D']

while unassigned:
    best_surplus = float('-inf')
    best_person = None
    best_good = None

    for person in values:
        for good in unassigned:
            surplus = values[person][good]
            if surplus > best_surplus:
                best_surplus = surplus
                best_person = person
                best_good = good

    if best_surplus > 0:
        assignment[best_good] = best_person
        unassigned.remove(best_good)
    else:
        break

print(assignment) 
