    best_person = None
    max_value = float('-inf')

    for item in unassigned:
        for person in values:
            if values[person][item] > max_value:
                max_value = values[person][item]
                best_item = item
                best_person = person

    assignment[best_item] = best_person
    unassigned.remove(best_item)

